pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(address target) public {
        bytes memory callData = abi.encodeWithSignature("onERC721Received(address,address,uint256,bytes)", address(0), address(0), uint256(0), bytes(""));
        (bool ok, bytes memory data) = address(c).call(callData);

        assertTrue(!ok || abi.decode(data, (bytes4)) == bytes4(0x150b7a02));
    }
}
